type ValidationError struct{ Message string }

func (e *ValidationError) Error() string {
	if e.Message != "" {
		return "webgpu: validation: " + e.Message
	}
	return "webgpu: validation"
}

type OutOfMemoryError struct{ Message string }

func (e *OutOfMemoryError) Error() string {
	if e.Message != "" {
		return "webgpu: out of memory: " + e.Message
	}
	return "webgpu: out of memory"
}

type InternalError struct{ Message string }

func (e *InternalError) Error() string {
	if e.Message != "" {
		return "webgpu: internal: " + e.Message
	}
	return "webgpu: internal"
}

type UnknownError struct{ Message string }

func (e *UnknownError) Error() string {
	if e.Message != "" {
		return "webgpu: unknown: " + e.Message
	}
	return "webgpu: unknown"
}

func errorFromErrorType(t ErrorType, message string) error {
	switch t {
	case ErrorTypeValidation:
		return &ValidationError{Message: message}
	case ErrorTypeOutOfMemory:
		return &OutOfMemoryError{Message: message}
	case ErrorTypeInternal:
		return &InternalError{Message: message}
	case ErrorTypeUnknown:
		return &UnknownError{Message: message}
	}
	return nil
}

var (
	instanceMu    sync.Mutex
	liveInstances []Instance
)

func addInstance(i Instance) {
	instanceMu.Lock()
	liveInstances = append(liveInstances, i)
	instanceMu.Unlock()
}

func removeInstance(i Instance) {
	instanceMu.Lock()
	for j, x := range liveInstances {
		if x == i {
			liveInstances = append(liveInstances[:j], liveInstances[j+1:]...)
			break
		}
	}
	instanceMu.Unlock()
}

func pumpEvents() {
	instanceMu.Lock()
	insts := make([]Instance, len(liveInstances))
	copy(insts, liveInstances)
	instanceMu.Unlock()
	for _, in := range insts {
		InstanceProcessEvents(in)
	}
}

func waitRecv[T any](ch <-chan T) T {
	for {
		select {
		case v := <-ch:
			return v
		default:
			pumpEvents()
			runtime.Gosched()
		}
	}
}

func wrapInstance(inner unsafe.Pointer) Instance {
	i := Instance(inner)
	if i != nil {
		addInstance(i)
	}
	return i
}

